// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address user) public {
        vm.assume(user != address(0));
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();
        uint256 returned = c.getBalance(user);
        assertTrue(returned == amount);
    }
}
